-- Install after supabase-modules.sql. No browser credentials or Google tokens here.

create table ops_private.report_worker_auth (
 singleton boolean primary key default true check(singleton),
 token text not null default (gen_random_uuid()::text||gen_random_uuid()::text)
);
insert into ops_private.report_worker_auth(singleton) values(true);
alter table ops_private.report_worker_auth enable row level security;
revoke all on ops_private.report_worker_auth from public,anon,authenticated;
grant usage on schema ops_private to service_role;
grant select on ops_private.report_worker_auth to service_role;
create function public.ops_is_report_worker(candidate text) returns boolean
 language sql stable security invoker set search_path='' as $$
 select candidate<>'' and exists(select 1 from ops_private.report_worker_auth where token=candidate)
$$;
revoke all on function public.ops_is_report_worker(text) from public,anon,authenticated;
grant execute on function public.ops_is_report_worker(text) to service_role;
-- pg_cron persists the schedule; pg_net executes while every browser is closed.
select cron.schedule('ops-safety-reports','* * * * *', $cron$
 select net.http_post(
  url:='https://dxhlobdjcfhjatyxrntx.supabase.co/functions/v1/ops-reports',
  headers:=jsonb_build_object('Content-Type','application/json','Authorization','Bearer '||(select token from ops_private.report_worker_auth where singleton)),
  body:='{}'::jsonb,
  timeout_milliseconds:=90000
 );
$cron$);

commit;
